-- ============================================================================
-- Campanha Fácil: Cartão Recorrente e variáveis de parcelamento com as vezes
-- ============================================================================
--
-- ## Por que
--
-- Pedido de 27/10/2026 (Cleber):
--
--   1. «Vai ser criada a variável de cartão recorrente… clonando o card de Pix
--      automático… e adicionar um campo de desconto.» Pix Automático e Cartão
--      Recorrente nunca saem com parcela abaixo de R$ 30; as outras formas o
--      líder pode manter.
--
--   2. As variáveis de parcelamento passam a sair com as vezes: {{cartao_quitacao}}
--      era «R$ 59,00» e agora é «12x de R$ 59,00». É o que deixa a campanha
--      refazer o parcelamento («21x de R$ 15,00» → «10x de R$ 32,00») quando a
--      parcela fica abaixo do mínimo. Para a mensagem não dizer «12x de 12x de
--      R$ 59,00», o «12x de» escrito antes da variável sai do texto.
--
-- ## O que muda
--
-- 1. `campanha_facil_descontos.cartao_recorrente`: o % do Cartão Recorrente,
--    padrão 5 (o mesmo do Pix Automático).
--
-- 2. As mensagens dos setores (`campanha_facil_mensagens`) que usam variável de
--    parcelamento: 125 das 127 lidas em 27/10/2026. Cada uma troca o texto
--    SÓ SE ainda estiver igual ao lido — mensagem editada depois disso fica como
--    está (o front também tira o «12x de» repetido na hora de montar a campanha,
--    e o editor avisa com «Corrigir»).
--    Regra: o «12x de», «12 vezes:», «20x de R$» colado na variável sai; quando
--    as vezes estavam longe da variável («Quitação em 12x no cartão: …») ou
--    faltavam, a linha foi reescrita à mão. Uma mensagem dizia «12x» com a
--    variável de 6x da junção: ficou o que a variável sempre mandou, 6x.
--
-- Os modelos padrão (os que vêm no código) mudaram junto, no front.
-- As campanhas já lançadas não mudam: guardaram o texto e os valores do dia.
--
-- Reaplicável: na segunda vez nenhuma mensagem casa com o texto antigo.
-- ============================================================================

BEGIN;

SET LOCAL lock_timeout = '15s';
SET LOCAL statement_timeout = '120s';

-- ── 1. Desconto do Cartão Recorrente ─────────────────────────────────────────

ALTER TABLE public.campanha_facil_descontos
  ADD COLUMN IF NOT EXISTS cartao_recorrente NUMERIC NOT NULL DEFAULT 5;

-- ── 2. As mensagens dos setores ──────────────────────────────────────────────

CREATE TEMP TABLE _cf_conversao (
  id     UUID PRIMARY KEY,
  antes  TEXT NOT NULL,
  depois TEXT NOT NULL
) ON COMMIT DROP;

INSERT INTO _cf_conversao (id, antes, depois) VALUES
  ('17ee660b-fb2f-406a-b116-dd51acb320d4'::UUID,
   E'*INSTAURAÇÃO DE PROCESSO JURÍDICO*\n\nOlá {{nome}}, portadora do CPF {{cpf}}, *protocolo {{contrato}}\n\nInformamos que á *recusa de acordo* junto à empresa a *{{empresa}}.* _De acordo com os artigos 389, 395 e 397 do Código Civil, o descumprimento da obrigação poderá acarretar o  bloqueio patrimonial envolvendo contas bancárias (30% de contas salário e corrente), CNPJ vinculado, CNH, cartões de credito, e benefícios governamentais.(bolsa família, CPC e aposentadoria mediante ordem judicial) até que haja resolução do conflito_. Diante disso, fica disponibilizado na *data de hoje* para regularização do débito. Diante disso foi gerado a notificação para ser entregue no endereço {{endereco}}\n\n*PROPOSTAS DISPONÍVEIS PARA REGULARIZAÇÃO:*\n\n*DIGITE 1* - *Quitação de todas as parcelas* à vista por *R$ {{quitacao}}* via *PIX OU BOLETO*\n*DIGITE 2* - *Parcelamento no cartão de crédito* em até *12x de R$ {{cartao_quitacao}}* sem juros\n*DIGITE 3* - *Regularizar o pagamento do acordo anterior na data de hoje*\n*DIGITE 4* - *Contraproposta informe seu valor à vista para análise hoje*\n\n*Qual das opções para quitação e extinção do pedido de processo?*\nOuvidoria : *{{atendimento}}* - Site: *Pagueplay*"',
   E'*INSTAURAÇÃO DE PROCESSO JURÍDICO*\n\nOlá {{nome}}, portadora do CPF {{cpf}}, *protocolo {{contrato}}\n\nInformamos que á *recusa de acordo* junto à empresa a *{{empresa}}.* _De acordo com os artigos 389, 395 e 397 do Código Civil, o descumprimento da obrigação poderá acarretar o  bloqueio patrimonial envolvendo contas bancárias (30% de contas salário e corrente), CNPJ vinculado, CNH, cartões de credito, e benefícios governamentais.(bolsa família, CPC e aposentadoria mediante ordem judicial) até que haja resolução do conflito_. Diante disso, fica disponibilizado na *data de hoje* para regularização do débito. Diante disso foi gerado a notificação para ser entregue no endereço {{endereco}}\n\n*PROPOSTAS DISPONÍVEIS PARA REGULARIZAÇÃO:*\n\n*DIGITE 1* - *Quitação de todas as parcelas* à vista por *R$ {{quitacao}}* via *PIX OU BOLETO*\n*DIGITE 2* - *Parcelamento no cartão de crédito* em até *{{cartao_quitacao}}* sem juros\n*DIGITE 3* - *Regularizar o pagamento do acordo anterior na data de hoje*\n*DIGITE 4* - *Contraproposta informe seu valor à vista para análise hoje*\n\n*Qual das opções para quitação e extinção do pedido de processo?*\nOuvidoria : *{{atendimento}}* - Site: *Pagueplay*"'),
  ('43b04256-509d-40a5-b8ad-da40de3012d8'::UUID,
   E'Olá, {{primeiro_nome}}.\n\nDÍVIDA EM FASE ATUAL DE PROCESSO\nProtocolo: {{protocolo}}102026\n\nConforme prevê sua contratação, e considerando o não pagamento das obrigações pactuadas, a credora {{empresa}} poderá ingressar com ação judicial de cobrança, respaldada pelo artigo 389 do Código Civil. \n\nA ausência de retorno resultará no pedido de medidas judiciais de restrição patrimonial e financeira, tais como:\n\n* Bloqueio e penhora de valores em contas bancárias;\n* Bloqueio de CNPJ e cartões de crédito;\n* Penhora de até 30% de rendimentos/conta-salário;\n\nCondições habilitadas para resolução imediatas:\n1. Quitação de todas as parcelas à vista de {{valor_com_juros}} por {{quitacao}} via PIX/BOLETO\n2. Parcelamento de todas as no cartão de crédito em até 12x de {{cartao_quitacao}}\n3. Parcelamento de todas as parcelas no PIX automático em 28x de R$ 178,57\n4. Contraproposta informe seu valor à vista para análise hoje.\n\nQual seu posicionamento para resolução?\nOuvidoria: {{atendimento}} - Site: Pagueplay',
   E'Olá, {{primeiro_nome}}.\n\nDÍVIDA EM FASE ATUAL DE PROCESSO\nProtocolo: {{protocolo}}102026\n\nConforme prevê sua contratação, e considerando o não pagamento das obrigações pactuadas, a credora {{empresa}} poderá ingressar com ação judicial de cobrança, respaldada pelo artigo 389 do Código Civil. \n\nA ausência de retorno resultará no pedido de medidas judiciais de restrição patrimonial e financeira, tais como:\n\n* Bloqueio e penhora de valores em contas bancárias;\n* Bloqueio de CNPJ e cartões de crédito;\n* Penhora de até 30% de rendimentos/conta-salário;\n\nCondições habilitadas para resolução imediatas:\n1. Quitação de todas as parcelas à vista de {{valor_com_juros}} por {{quitacao}} via PIX/BOLETO\n2. Parcelamento de todas as no cartão de crédito em até {{cartao_quitacao}}\n3. Parcelamento de todas as parcelas no PIX automático em 28x de R$ 178,57\n4. Contraproposta informe seu valor à vista para análise hoje.\n\nQual seu posicionamento para resolução?\nOuvidoria: {{atendimento}} - Site: Pagueplay'),
  ('3b7c411c-4e06-4815-bcc8-b5d8e0001fd0'::UUID,
   E'*ENCAMINHAMENTO DE PROCESSO POR ENRIQUECIMENTO ILÍCITO*\n\nPrezada(o) *{{nome}}* - CPF: *{{cpf}}*\n\nConforme o compromisso firmado da sua compra com a *{{empresa}}*, e diante da *ausência de acordo amigável*, a credora já manifestou intenção de *ingressar com ação judicial*, com base no *Art. 884 do Código Civil (enriquecimento ilícito)*.\n\n*Citação registrada para o endereço:*  \n{{local_trabalho}}\n\nO processo refere-se a a ausência de pagamentos do *contrato {{contrato}} tácito firmado*. O caso poderá resultar em *execução forçada, resolução contratual e indenização por perdas e danos*.\n\n*Prazo final*: Com amparo da lei de *nº. 13.140/15*, para conciliação a empresa é obrigada hoje a realizar a retirada de acréscimos, retornando ao valor original.\n\n*Opções para resolução imediatas:*\n1. *Quitação de todas as parcelas á vista* de *~R$ {{valor_com_juros}}~* por *R$ {{quitacao}}*  \n2. *Parcelamento no cartão de crédito* em até *12x de R$ {{cartao_quitacao}}* sem juros  \n3. *Contraproposta informe seu valor à vista para análise hoje.*\n\n*Qual seu posicionamento para resolução hoje?* \nOuvidoria : *{{atendimento}}* - Site: *Pagueplay*',
   E'*ENCAMINHAMENTO DE PROCESSO POR ENRIQUECIMENTO ILÍCITO*\n\nPrezada(o) *{{nome}}* - CPF: *{{cpf}}*\n\nConforme o compromisso firmado da sua compra com a *{{empresa}}*, e diante da *ausência de acordo amigável*, a credora já manifestou intenção de *ingressar com ação judicial*, com base no *Art. 884 do Código Civil (enriquecimento ilícito)*.\n\n*Citação registrada para o endereço:*  \n{{local_trabalho}}\n\nO processo refere-se a a ausência de pagamentos do *contrato {{contrato}} tácito firmado*. O caso poderá resultar em *execução forçada, resolução contratual e indenização por perdas e danos*.\n\n*Prazo final*: Com amparo da lei de *nº. 13.140/15*, para conciliação a empresa é obrigada hoje a realizar a retirada de acréscimos, retornando ao valor original.\n\n*Opções para resolução imediatas:*\n1. *Quitação de todas as parcelas á vista* de *~R$ {{valor_com_juros}}~* por *R$ {{quitacao}}*  \n2. *Parcelamento no cartão de crédito* em até *{{cartao_quitacao}}* sem juros  \n3. *Contraproposta informe seu valor à vista para análise hoje.*\n\n*Qual seu posicionamento para resolução hoje?* \nOuvidoria : *{{atendimento}}* - Site: *Pagueplay*'),
  ('6a48ba04-2255-4f8f-917e-a86b46331da1'::UUID,
   E'*ATENÇÃO! PEDIDO DE BLOQUEIOS POR FALTA DE PAGAMENTOS!*\n\nPrezada(o) *{{nome}}* - CPF: *{{cpf}}*\n\nEstamos em posse de um documento expedido em sua titularidade, com *solicitação de bloqueios*.\n*Citação registrada para o endereço:*  \n{{local_trabalho}}\n\nConforme o compromisso firmado com a *{{empresa}}*, e diante da *ausência de acordo amigável*, a credora já manifestou intenção de *ingressar com ação judicial*, com base no *Art. 884 do Código Civil (enriquecimento ilícito)*.\n\n*Prazo final*: Com amparo da lei de *nº. 13.140/15*, para conciliação a empresa é obrigada a realizar a retirada de acréscimos, retornando ao valor original.\n\n*Opções para resolução imediatas:*\n1. *Quitação de todas as parcelas á vista* de *~{{valor_com_juros}}~* por *{{quitacao}}*  \n2. *Quitação no cartão de crédito (próprio ou terceiros)* em até *12x de {{cartao_quitacao}}*  \n3. *Contraproposta informe seu valor à vista para análise hoje.*\n\n*Como irá negociar e resolver sua situação hoje?* \nSAC: *{{atendimento}}* - Site: *Pagueplay*',
   E'*ATENÇÃO! PEDIDO DE BLOQUEIOS POR FALTA DE PAGAMENTOS!*\n\nPrezada(o) *{{nome}}* - CPF: *{{cpf}}*\n\nEstamos em posse de um documento expedido em sua titularidade, com *solicitação de bloqueios*.\n*Citação registrada para o endereço:*  \n{{local_trabalho}}\n\nConforme o compromisso firmado com a *{{empresa}}*, e diante da *ausência de acordo amigável*, a credora já manifestou intenção de *ingressar com ação judicial*, com base no *Art. 884 do Código Civil (enriquecimento ilícito)*.\n\n*Prazo final*: Com amparo da lei de *nº. 13.140/15*, para conciliação a empresa é obrigada a realizar a retirada de acréscimos, retornando ao valor original.\n\n*Opções para resolução imediatas:*\n1. *Quitação de todas as parcelas á vista* de *~{{valor_com_juros}}~* por *{{quitacao}}*  \n2. *Quitação no cartão de crédito (próprio ou terceiros)* em até *{{cartao_quitacao}}*  \n3. *Contraproposta informe seu valor à vista para análise hoje.*\n\n*Como irá negociar e resolver sua situação hoje?* \nSAC: *{{atendimento}}* - Site: *Pagueplay*'),
  ('61b4d06d-9a4e-4e19-b60f-b3d147db8e68'::UUID,
   E'🚨 *ATENÇÃO, {{primeiro_nome}}! UMA CONDIÇÃO ESPECIAL FOI LIBERADA PARA VOCÊ!*\n\n💥 *CHEGOU A CHANCE DE REGULARIZAR SEU CONTRATO COM ATÉ {{pct_quitacao}} DE DESCONTO!*\nSeu contrato *{{contrato}}*, junto à *{{empresa}}*, foi selecionado hoje, *20/10/2026*, para uma negociação com condições diferenciadas!\n*Confira as opções disponíveis para regularizar seu CPF {{cpf}}:*\n\n1️⃣ *PIX AUTOMÁTICO: {{pct_pix_automatico}}\n2️⃣ *PARCELAS EM ATRASO:* pague somente as parcelas vencidas, com *{{pct_atraso}}*, por *{{parcela_desconto}}*.\n3️⃣ *PARCELAS ATRASADAS + A VENCER:* com *{{pct_juncao}}*, por *{{juncao}}*.\n4️⃣ *QUITAÇÃO TOTAL:* com *{{pct_quitacao}}*, parcelando em até *12x de {{cartao_quitacao}}* no cartão de crédito. *Aceitamos cartão de terceiros!*\n5️⃣ *ANUIDADE:* aproveite *{{pct_anual}}*, em até *12x de {{cartao_anual}}* no cartão de crédito.\n\n🎁 *BENEFÍCIO EXCLUSIVO:* escolhendo a quitação total, você ainda garante *4 MESES DE ACESSO GRATUITO!*\n\n*QUAL DESSAS OPÇÕES FICA MELHOR PARA VOCÊ?*',
   E'🚨 *ATENÇÃO, {{primeiro_nome}}! UMA CONDIÇÃO ESPECIAL FOI LIBERADA PARA VOCÊ!*\n\n💥 *CHEGOU A CHANCE DE REGULARIZAR SEU CONTRATO COM ATÉ {{pct_quitacao}} DE DESCONTO!*\nSeu contrato *{{contrato}}*, junto à *{{empresa}}*, foi selecionado hoje, *20/10/2026*, para uma negociação com condições diferenciadas!\n*Confira as opções disponíveis para regularizar seu CPF {{cpf}}:*\n\n1️⃣ *PIX AUTOMÁTICO: {{pct_pix_automatico}}\n2️⃣ *PARCELAS EM ATRASO:* pague somente as parcelas vencidas, com *{{pct_atraso}}*, por *{{parcela_desconto}}*.\n3️⃣ *PARCELAS ATRASADAS + A VENCER:* com *{{pct_juncao}}*, por *{{juncao}}*.\n4️⃣ *QUITAÇÃO TOTAL:* com *{{pct_quitacao}}*, parcelando em até *{{cartao_quitacao}}* no cartão de crédito. *Aceitamos cartão de terceiros!*\n5️⃣ *ANUIDADE:* aproveite *{{pct_anual}}*, em até *{{cartao_anual}}* no cartão de crédito.\n\n🎁 *BENEFÍCIO EXCLUSIVO:* escolhendo a quitação total, você ainda garante *4 MESES DE ACESSO GRATUITO!*\n\n*QUAL DESSAS OPÇÕES FICA MELHOR PARA VOCÊ?*'),
  ('429983b0-03b6-46bc-9e81-5fff1c53574e'::UUID,
   E'💰 *PAGUE SUA PARCELA EM ATRASO COM DESCONTO!* 💰\n\nOlá, *{{nome}}*. \nTenho uma *OFERTA EXCLUSIVA* para você regularizar sua pendência na {{empresa}} referente ao contrato *{{contrato}}*!\n\n1️⃣ *{{pct_pix_automatico}} DE DESCONTO* na ativação do *PIX RECORRENTE* todo mês\n2️⃣ *{{pct_atraso}} DE DESCONTO* nas parcelas em atraso — *{{parcela_desconto}}*\n3️⃣ *{{pct_juncao}} DE DESCONTO* na regularização das parcelas vencidas + próxima — *{{juncao}}*\n4️⃣ *{{pct_quitacao}} DE DESCONTO* para quitação total via Pix — *{{quitacao}}*\n5️⃣ *{{pct_quitacao}} DE DESCONTO* no cartão em até *12x de {{cartao_quitacao}}* (podendo ser de terceiros)\n\n💬 _Podemos enviar o link para pagamento agora?_\n',
   E'💰 *PAGUE SUA PARCELA EM ATRASO COM DESCONTO!* 💰\n\nOlá, *{{nome}}*. \nTenho uma *OFERTA EXCLUSIVA* para você regularizar sua pendência na {{empresa}} referente ao contrato *{{contrato}}*!\n\n1️⃣ *{{pct_pix_automatico}} DE DESCONTO* na ativação do *PIX RECORRENTE* todo mês\n2️⃣ *{{pct_atraso}} DE DESCONTO* nas parcelas em atraso — *{{parcela_desconto}}*\n3️⃣ *{{pct_juncao}} DE DESCONTO* na regularização das parcelas vencidas + próxima — *{{juncao}}*\n4️⃣ *{{pct_quitacao}} DE DESCONTO* para quitação total via Pix — *{{quitacao}}*\n5️⃣ *{{pct_quitacao}} DE DESCONTO* no cartão em até *{{cartao_quitacao}}* (podendo ser de terceiros)\n\n💬 _Podemos enviar o link para pagamento agora?_\n'),
  ('7c59ee36-c02c-40e1-a59f-bca796815d91'::UUID,
   E'*🚨 ATENÇÃO {{primeiro_nome}}, PRECISAMOS REGULARIZAR SUA PENDÊNCIA!*\n\n📌 Protocolo: *{{contrato}}*.\nOlá, *{{nome}}*! Tudo bem?\nMe chamo *Izadora* e faço parte do setor financeiro da **.\n\nIdentificamos um débito pendente junto à *{{empresa}}*. Solicitamos seu retorno urgente para regularização, evitando possíveis medidas legais de cobrança, incluindo negativação do CPF e eventual cobrança judicial, conforme a legislação vigente.\n\n*💰 Temos condições especiais disponíveis para facilitar sua regularização:*\n\n1️⃣ {{pct_atraso}} de desconto na parcela em atraso: *{{parcela_desconto}}*.\n2️⃣ {{pct_juncao}} de desconto na junção da parcela em atraso + parcela a vencer: *{{juncao}}*.\n3️⃣ {{pct_quitacao}} de desconto para quitação em até 12x de *{{cartao_quitacao}}* no cartão de crédito (aceitamos cartão de terceiros com a possibilidade do parcelamento em ate 21x).\n4️⃣ Quitação via Pix por apenas *{{quitacao}}*.\n5️⃣🎯 *ANTECIPAÇÃO DA ANUIDADE* — (Antecipe 12 meses do boleto) e aproveite {{pct_anual}} de desconto, com pagamento em até 12x de *{{cartao_anual}}* no cartão de crédito.\n6️⃣ Pagamento pelo Pix automático com *{{pct_pix_automatico}} OFF*.\n\n*⚠️ Importante: A permanência da inadimplência poderá resultar na inclusão do débito em cadastros de proteção ao crédito, como Serasa e SPC, observados os requisitos legais, além da cobrança pelos meios legalmente cabíveis.*\n\n_📲 Entre em contato ainda hoje e informe o número da opção desejada para regularizar sua situação e evitar o prolongamento dessa pendência._',
   E'*🚨 ATENÇÃO {{primeiro_nome}}, PRECISAMOS REGULARIZAR SUA PENDÊNCIA!*\n\n📌 Protocolo: *{{contrato}}*.\nOlá, *{{nome}}*! Tudo bem?\nMe chamo *Izadora* e faço parte do setor financeiro da **.\n\nIdentificamos um débito pendente junto à *{{empresa}}*. Solicitamos seu retorno urgente para regularização, evitando possíveis medidas legais de cobrança, incluindo negativação do CPF e eventual cobrança judicial, conforme a legislação vigente.\n\n*💰 Temos condições especiais disponíveis para facilitar sua regularização:*\n\n1️⃣ {{pct_atraso}} de desconto na parcela em atraso: *{{parcela_desconto}}*.\n2️⃣ {{pct_juncao}} de desconto na junção da parcela em atraso + parcela a vencer: *{{juncao}}*.\n3️⃣ {{pct_quitacao}} de desconto para quitação em até *{{cartao_quitacao}}* no cartão de crédito (aceitamos cartão de terceiros com a possibilidade do parcelamento em ate 21x).\n4️⃣ Quitação via Pix por apenas *{{quitacao}}*.\n5️⃣🎯 *ANTECIPAÇÃO DA ANUIDADE* — (Antecipe 12 meses do boleto) e aproveite {{pct_anual}} de desconto, com pagamento em até *{{cartao_anual}}* no cartão de crédito.\n6️⃣ Pagamento pelo Pix automático com *{{pct_pix_automatico}} OFF*.\n\n*⚠️ Importante: A permanência da inadimplência poderá resultar na inclusão do débito em cadastros de proteção ao crédito, como Serasa e SPC, observados os requisitos legais, além da cobrança pelos meios legalmente cabíveis.*\n\n_📲 Entre em contato ainda hoje e informe o número da opção desejada para regularizar sua situação e evitar o prolongamento dessa pendência._'),
  ('68b5f6ce-2f39-44ba-b733-da31c7c9f50e'::UUID,
   E'*⚠️ INADIMPLÊNCIA LOCALIZADA– CONDIÇÃO ESPECIAL PARA QUITAÇÃO*\n\nRegularize sua pendência o quanto antes! Aproveite a condição especial de quitação com {{pct_quitacao}} de desconto, válida para quem deseja resolver sua dívida com um valor reduzido.\n\nOlá, *{{nome}}* !\nSou *Pedro* do setor financeiro da *{{empresa}}*. 📌 Protocolo: *{{contrato}}*\nIdentificamos que seu acordo está pendente. Regularize ainda HOJE para evitar o cancelamento dos benefícios e aproveite a condição especial de quitação com *{{pct_quitacao}} de desconto em seu contrato!*\n\n1️⃣ 💰 *PIX — ISENÇÃO DE JUROS* Quite apenas as parcelas EM ATRASO por *{{parcela_desconto}}*\n2️⃣ 🔥 *JUNÇÃO DAS PARCELAS* — {{pct_juncao}} DE DESCONTO Una as parcelas em atraso com a próxima a vencer e pague apenas *{{juncao}}*.\n3️⃣ 💳 *CARTÃO DE CRÉDITO* — {{pct_quitacao}} DE DESCONTO Parcele em até *12x de {{cartao_quitacao}}*. O pagamento pode ser realizado com cartão de terceiros.\n4️⃣ 🎯 *ANTECIPAÇÃO DA ANUIDADE* — (Antecipe 12 meses do boleto) e aproveite {{pct_anual}} de desconto, com pagamento em até *12x de {{cartao_anual}}* no cartão de crédito.\n\n📌 Escolha a opção mais adequada e regularize sua situação o quanto antes. Aproveite as condições disponíveis e não deixe sua pendência em aberto!',
   E'*⚠️ INADIMPLÊNCIA LOCALIZADA– CONDIÇÃO ESPECIAL PARA QUITAÇÃO*\n\nRegularize sua pendência o quanto antes! Aproveite a condição especial de quitação com {{pct_quitacao}} de desconto, válida para quem deseja resolver sua dívida com um valor reduzido.\n\nOlá, *{{nome}}* !\nSou *Pedro* do setor financeiro da *{{empresa}}*. 📌 Protocolo: *{{contrato}}*\nIdentificamos que seu acordo está pendente. Regularize ainda HOJE para evitar o cancelamento dos benefícios e aproveite a condição especial de quitação com *{{pct_quitacao}} de desconto em seu contrato!*\n\n1️⃣ 💰 *PIX — ISENÇÃO DE JUROS* Quite apenas as parcelas EM ATRASO por *{{parcela_desconto}}*\n2️⃣ 🔥 *JUNÇÃO DAS PARCELAS* — {{pct_juncao}} DE DESCONTO Una as parcelas em atraso com a próxima a vencer e pague apenas *{{juncao}}*.\n3️⃣ 💳 *CARTÃO DE CRÉDITO* — {{pct_quitacao}} DE DESCONTO Parcele em até *{{cartao_quitacao}}*. O pagamento pode ser realizado com cartão de terceiros.\n4️⃣ 🎯 *ANTECIPAÇÃO DA ANUIDADE* — (Antecipe 12 meses do boleto) e aproveite {{pct_anual}} de desconto, com pagamento em até *{{cartao_anual}}* no cartão de crédito.\n\n📌 Escolha a opção mais adequada e regularize sua situação o quanto antes. Aproveite as condições disponíveis e não deixe sua pendência em aberto!'),
  ('8d199338-bb7d-4f5f-a549-ec8ba9f19add'::UUID,
   E'🎯 *DESCONTO EXCLUSIVO: SUA PARCELA EM ATRASO POR APENAS {{parcela_desconto}}* \n\nOlá, *{{nome}}* \n📢 Olha só o *DESCONTO ESPECIAL* para regularização do contrato *{{contrato}}* junto à {{empresa}}. Me chamo Bruna e vou te ajudar!\n\n1️⃣ Pagamento pelo pix automático com 10% OFF* \n2️⃣ Pagamento somente da parcelas em atraso com *{{pct_atraso}}*: {{parcela_desconto}}\n3️⃣ *{{pct_juncao}}* na junção (parcela atrasada + à vencer): {{juncao}}\n4️⃣ *{{pct_quitacao}}* para quitação em até *12x de {{cartao_quitacao}}* no cartão de crédito (aceitamos cartão de terceiros) \n5️⃣ Anuidade (12 boletos) com *{{pct_anual}}* em até *12x de {{cartao_anual}}* no cartão de crédito \n\n🎁 _Pagando a quitação, você ainda garante 4 meses de acesso gratuito._\n\n📌 *Como Podemos Concluir?*',
   E'🎯 *DESCONTO EXCLUSIVO: SUA PARCELA EM ATRASO POR APENAS {{parcela_desconto}}* \n\nOlá, *{{nome}}* \n📢 Olha só o *DESCONTO ESPECIAL* para regularização do contrato *{{contrato}}* junto à {{empresa}}. Me chamo Bruna e vou te ajudar!\n\n1️⃣ Pagamento pelo pix automático com 10% OFF* \n2️⃣ Pagamento somente da parcelas em atraso com *{{pct_atraso}}*: {{parcela_desconto}}\n3️⃣ *{{pct_juncao}}* na junção (parcela atrasada + à vencer): {{juncao}}\n4️⃣ *{{pct_quitacao}}* para quitação em até *{{cartao_quitacao}}* no cartão de crédito (aceitamos cartão de terceiros) \n5️⃣ Anuidade (12 boletos) com *{{pct_anual}}* em até *{{cartao_anual}}* no cartão de crédito \n\n🎁 _Pagando a quitação, você ainda garante 4 meses de acesso gratuito._\n\n📌 *Como Podemos Concluir?*'),
  ('d5910bb5-611e-4a13-806c-49597038ac1e'::UUID,
   E'💰 *PAGUE SUA PARCELA EM ATRASO COM {{pct_atraso}} DE DESCONTO!* 💰\n\nOlá, *{{nome}}*. \nTenho uma *OFERTA EXCLUSIVA* para você regularizar sua pendência na {{empresa}} referente ao contrato *{{contrato}}*!\n\n1️⃣ *{{pct_pix_automatico}} DE DESCONTO* na ativação do *PIX RECORRENTE* todo mês\n2️⃣ *{{pct_atraso}} DE DESCONTO* nas parcelas em atraso — *{{parcela_desconto}}*\n3️⃣ *{{pct_juncao}} DE DESCONTO* na regularização das parcelas vencidas + próxima — *{{juncao}}*\n4️⃣ *{{pct_quitacao}} DE DESCONTO* para quitação total via Pix — *{{quitacao}}*\n5️⃣ *{{pct_quitacao}} DE DESCONTO* no cartão em até *12x de {{cartao_quitacao}}* (podendo ser de terceiros)\n\n💬 _Podemos enviar o link para pagamento agora?_\n',
   E'💰 *PAGUE SUA PARCELA EM ATRASO COM {{pct_atraso}} DE DESCONTO!* 💰\n\nOlá, *{{nome}}*. \nTenho uma *OFERTA EXCLUSIVA* para você regularizar sua pendência na {{empresa}} referente ao contrato *{{contrato}}*!\n\n1️⃣ *{{pct_pix_automatico}} DE DESCONTO* na ativação do *PIX RECORRENTE* todo mês\n2️⃣ *{{pct_atraso}} DE DESCONTO* nas parcelas em atraso — *{{parcela_desconto}}*\n3️⃣ *{{pct_juncao}} DE DESCONTO* na regularização das parcelas vencidas + próxima — *{{juncao}}*\n4️⃣ *{{pct_quitacao}} DE DESCONTO* para quitação total via Pix — *{{quitacao}}*\n5️⃣ *{{pct_quitacao}} DE DESCONTO* no cartão em até *{{cartao_quitacao}}* (podendo ser de terceiros)\n\n💬 _Podemos enviar o link para pagamento agora?_\n'),
  ('cd31bb19-798e-47e7-a4e5-c7c123c3aab6'::UUID,
   E'*AVISO PRÉVIO: EVITE O PROTESTO DO CPF {{cpf}}*\n\n*ATENÇÃO: {{nome}}*. Informamos que em *48 horas* a dívida será enviada ao Cartório de Protesto de Títulos e Documentos, devido a negligência com os pagamentos do contrato *{{contrato}}*.\n\n1️⃣ *{{pct_pix_automatico}} DE DESCONTO* na ativação do PIX RECORRENTE — *{{pix_automatico_desconto_20x}}*/ todo mês\n2️⃣ *{{pct_atraso}} DE DESCONTO* na parcela em atraso com a proxima a vencer — *{{parcela_desconto}}*\n3️⃣ *{{pct_juncao}} DE DESCONTO* na regularização das parcelas vencidas + próxima — *{{juncao}}*\n4️⃣ *{{pct_quitacao}} DE DESCONTO* para quitação total via Pix — *{{quitacao}}*\n5️⃣ *{{pct_quitacao}} DE DESCONTO* no cartão em até *12x de {{cartao_quitacao}}* (podendo ser de terceiros)\n\n*Qual a melhor opção para evitar protesto?*\n',
   E'*AVISO PRÉVIO: EVITE O PROTESTO DO CPF {{cpf}}*\n\n*ATENÇÃO: {{nome}}*. Informamos que em *48 horas* a dívida será enviada ao Cartório de Protesto de Títulos e Documentos, devido a negligência com os pagamentos do contrato *{{contrato}}*.\n\n1️⃣ *{{pct_pix_automatico}} DE DESCONTO* na ativação do PIX RECORRENTE — *{{pix_automatico_desconto_20x}}*/ todo mês\n2️⃣ *{{pct_atraso}} DE DESCONTO* na parcela em atraso com a proxima a vencer — *{{parcela_desconto}}*\n3️⃣ *{{pct_juncao}} DE DESCONTO* na regularização das parcelas vencidas + próxima — *{{juncao}}*\n4️⃣ *{{pct_quitacao}} DE DESCONTO* para quitação total via Pix — *{{quitacao}}*\n5️⃣ *{{pct_quitacao}} DE DESCONTO* no cartão em até *{{cartao_quitacao}}* (podendo ser de terceiros)\n\n*Qual a melhor opção para evitar protesto?*\n'),
  ('64b84e16-2d11-4015-9806-cc2ccb55c146'::UUID,
   E'*CONDIÇÃO PREMIADA: 4 MESES EXTRAS NA QUITAÇÃO* 🎉\n\n📌 *Protocolo: *{{contrato}}*\nOlá, *{{nome}}*. Me chamo Cintia e faço parte do financeiro da *{{empresa}}*\nVerifiquei que consta um atraso em seus pagamentos. Regularize sua situação e aproveite o *DESCONTO EXCLUSIVO liberado no CPF!*\n\n1️⃣  Pagamento da parcelas em atraso com *{{pct_atraso}}*: {{parcela_desconto}}\n2️⃣ *{{pct_juncao}}* na junção (parcela atrasada + à vencer): {{juncao}}\n3️⃣ *{{pct_quitacao}}* para quitação em até *21x de {{cartao_quitacao_21x}}* no cartão de crédito (aceitamos cartão de terceiros)\n4️⃣ *Quitação no pix por {{quitacao}}*\n\n🎁 _Pagando a quitação, você ainda garante 4 meses de acesso gratuito_\n\n💬 *Confirma pra mim a opção desejada?*',
   E'*CONDIÇÃO PREMIADA: 4 MESES EXTRAS NA QUITAÇÃO* 🎉\n\n📌 *Protocolo: *{{contrato}}*\nOlá, *{{nome}}*. Me chamo Cintia e faço parte do financeiro da *{{empresa}}*\nVerifiquei que consta um atraso em seus pagamentos. Regularize sua situação e aproveite o *DESCONTO EXCLUSIVO liberado no CPF!*\n\n1️⃣  Pagamento da parcelas em atraso com *{{pct_atraso}}*: {{parcela_desconto}}\n2️⃣ *{{pct_juncao}}* na junção (parcela atrasada + à vencer): {{juncao}}\n3️⃣ *{{pct_quitacao}}* para quitação em até *{{cartao_quitacao_21x}}* no cartão de crédito (aceitamos cartão de terceiros)\n4️⃣ *Quitação no pix por {{quitacao}}*\n\n🎁 _Pagando a quitação, você ainda garante 4 meses de acesso gratuito_\n\n💬 *Confirma pra mim a opção desejada?*'),
  ('6c1a5f5f-a5ee-4370-90c3-a1aeded3e7a6'::UUID,
   E'*⚠️ URGENTE: ACORDO NÃO PAGO — REGULARIZE SUA SITUAÇÃO!*\n\n📌 Protocolo: *{{contrato}}*\nOlá,*{{nome}}*! Tudo bem? \nMe chamo "Paola" e faço parte do setor financeiro da *{{empresa}}*.\n\nIdentificamos que o acordo formalizado anteriormente não teve o pagamento identificado em nosso sistema. ⚠️ Por esse motivo, sua pendência permanece em aberto e precisamos da sua atenção para regularizar essa situação o quanto antes.\n*🚨 ⚠️ A falta de regularização poderá acarretar a perda das condições negociadas, atualização do débito com juros e encargos aplicáveis, continuidade dos procedimentos de cobrança e possível negativação do CPF, quando cabível.*\n\n1️⃣ *ISENÇÃO DE JUROS + {{pct_atraso}} OFF*  no pagamento na parcela em atraso: *{{parcela_desconto}}*\n2️⃣ {{pct_juncao}} de desconto na junção das parcelas em atraso + parcela a vencer: *{{juncao}}.*\n3️⃣ {{pct_quitacao}} de desconto para quitação em até 12x de *{{cartao_quitacao}}* no cartão de crédito (aceitamos cartão de terceiros).\n4️⃣ {{pct_anual}} de desconto no pagamento da ANUIDADE ( 12 boletos) por apenas *{{cartao_anual}}*.\n 5️⃣ Pagamento pelo Pix automático com *{{pct_pix_automatico}} OFF* por  {{pix_automatico_parcela}}.\n\n*⏰ Não deixe para depois! Entre em contato o quanto antes para consultar as condições disponíveis e regularizar seu débito. 💰*',
   E'*⚠️ URGENTE: ACORDO NÃO PAGO — REGULARIZE SUA SITUAÇÃO!*\n\n📌 Protocolo: *{{contrato}}*\nOlá,*{{nome}}*! Tudo bem? \nMe chamo "Paola" e faço parte do setor financeiro da *{{empresa}}*.\n\nIdentificamos que o acordo formalizado anteriormente não teve o pagamento identificado em nosso sistema. ⚠️ Por esse motivo, sua pendência permanece em aberto e precisamos da sua atenção para regularizar essa situação o quanto antes.\n*🚨 ⚠️ A falta de regularização poderá acarretar a perda das condições negociadas, atualização do débito com juros e encargos aplicáveis, continuidade dos procedimentos de cobrança e possível negativação do CPF, quando cabível.*\n\n1️⃣ *ISENÇÃO DE JUROS + {{pct_atraso}} OFF*  no pagamento na parcela em atraso: *{{parcela_desconto}}*\n2️⃣ {{pct_juncao}} de desconto na junção das parcelas em atraso + parcela a vencer: *{{juncao}}.*\n3️⃣ {{pct_quitacao}} de desconto para quitação em até *{{cartao_quitacao}}* no cartão de crédito (aceitamos cartão de terceiros).\n4️⃣ {{pct_anual}} de desconto no pagamento da ANUIDADE ( 12 boletos) por apenas *{{cartao_anual}}*.\n 5️⃣ Pagamento pelo Pix automático com *{{pct_pix_automatico}} OFF* por  {{pix_automatico_parcela}}.\n\n*⏰ Não deixe para depois! Entre em contato o quanto antes para consultar as condições disponíveis e regularizar seu débito. 💰*'),
  ('24f1fa8a-4008-42e8-ab89-6ddbd9f0ec79'::UUID,
   E'Sr(a). *{{nome}}.*\nMeu nome é Amanda e atuo como mediadora jurídica no *Tribunal de Justiça Administrativo (TJA).*\nComunico que recebi um documento emitido em seu nome, identificado pelo CPF *{{cpf}}*, no qual consta um pedido de bloqueios a serem analisados. A citação poderá ocorrer no fórum da sua região, local em que receberá a *Nota de Esclarecimento* emitida em seu nome, para fins de levantamento de renda ativa junto ao Município. \nDiante da ausência de resolução amigável, a credora manifestou sua intenção de ingressar com ação judicial por perdas e danos e enriquecimento ilícito, com fundamento no art. 884 do Código Civil.\n \nIremos tentar uma *ÚLTIMA* conciliação para coleta de assinatura. Protocolo *{{contrato}}* com a contratada *{{empresa}}.*\n \n1 - Quitação total de *R${{valor_com_juros}} por R${{quitacao}}*.\n2 - Cartão de crédito parcelado em até *12x de R${{cartao_quitacao}}*.\n3 - Pagar a parcela em atraso hoje: *R${{parcela_desconto}}*.\n4 - Pagar parcelas em atraso + a que vai vencer: *R${{juncao}}*\n5 - *Assumo a responsabilidade sobre as medidas cabíveis por falta de pagamento.*\n \nAcesse o site pagueplay.com - SAC {{atendimento}}\n*Digite a melhor opção para retroagir essa citação.*\n ',
   E'Sr(a). *{{nome}}.*\nMeu nome é Amanda e atuo como mediadora jurídica no *Tribunal de Justiça Administrativo (TJA).*\nComunico que recebi um documento emitido em seu nome, identificado pelo CPF *{{cpf}}*, no qual consta um pedido de bloqueios a serem analisados. A citação poderá ocorrer no fórum da sua região, local em que receberá a *Nota de Esclarecimento* emitida em seu nome, para fins de levantamento de renda ativa junto ao Município. \nDiante da ausência de resolução amigável, a credora manifestou sua intenção de ingressar com ação judicial por perdas e danos e enriquecimento ilícito, com fundamento no art. 884 do Código Civil.\n \nIremos tentar uma *ÚLTIMA* conciliação para coleta de assinatura. Protocolo *{{contrato}}* com a contratada *{{empresa}}.*\n \n1 - Quitação total de *R${{valor_com_juros}} por R${{quitacao}}*.\n2 - Cartão de crédito parcelado em até *{{cartao_quitacao}}*.\n3 - Pagar a parcela em atraso hoje: *R${{parcela_desconto}}*.\n4 - Pagar parcelas em atraso + a que vai vencer: *R${{juncao}}*\n5 - *Assumo a responsabilidade sobre as medidas cabíveis por falta de pagamento.*\n \nAcesse o site pagueplay.com - SAC {{atendimento}}\n*Digite a melhor opção para retroagir essa citação.*\n '),
  ('6291ed76-8a10-43d2-9c2d-d5d8e3b78b50'::UUID,
   E'*SÃO PAULO, 21 DE OUTUBRO DE 2026.*\n \nPrezado(a): *{{nome}}*\nCPF: *{{cpf}}*\n \nDentro de alguns dias, você poderá ser notificada em sua residência, por meio de oficial de justiça, para comparecer à cidade de Araçatuba/SP, a fim de participar de audiência de mediação, em razão do débito pendente junto à credora *{{empresa}}*, referente ao contrato nº *{{contrato}}*\n \nConsiderando que você não reside na mesma cidade e que a política da empresa não autoriza atendimento por videoconferência, segue a última oportunidade de regularização antes do envio da documentação, evitando a cobrança por medidas coercitivas, incluindo bloqueio de CNH, bloqueio de cartões de crédito e retenção de até 25% da renda familiar, conforme permitido em procedimentos extrajudiciais. *Valor atualizado hoje: {{valor_com_juros}}*\n \nOpções de resolução imediata:\n1 - Quitação de TODAS as parcelas via PIX por *{{quitacao}}*\n2 - Cartão de crédito (próprio ou de terceiros) em até *12x de {{cartao_quitacao}}*\n3 - Junção (parcelas em atraso + a vencer) por *{{juncao}}*\n4 - Regularização das parcelas em atraso sem juros por *{{parcela_desconto}}*\n5 - Simulação para parcelamento no Pix automático ou recorrência no cartão. \n \n*RETORNO EM ATÉ 1 HORA.*\nAcesse o site pagueplay.com ou SAC {{atendimento}}\n \n*A ausência de retorno será interpretada como recusa de negociação, ocasionando o prosseguimento da ação extrajudicial sem novo aviso.*',
   E'*SÃO PAULO, 21 DE OUTUBRO DE 2026.*\n \nPrezado(a): *{{nome}}*\nCPF: *{{cpf}}*\n \nDentro de alguns dias, você poderá ser notificada em sua residência, por meio de oficial de justiça, para comparecer à cidade de Araçatuba/SP, a fim de participar de audiência de mediação, em razão do débito pendente junto à credora *{{empresa}}*, referente ao contrato nº *{{contrato}}*\n \nConsiderando que você não reside na mesma cidade e que a política da empresa não autoriza atendimento por videoconferência, segue a última oportunidade de regularização antes do envio da documentação, evitando a cobrança por medidas coercitivas, incluindo bloqueio de CNH, bloqueio de cartões de crédito e retenção de até 25% da renda familiar, conforme permitido em procedimentos extrajudiciais. *Valor atualizado hoje: {{valor_com_juros}}*\n \nOpções de resolução imediata:\n1 - Quitação de TODAS as parcelas via PIX por *{{quitacao}}*\n2 - Cartão de crédito (próprio ou de terceiros) em até *{{cartao_quitacao}}*\n3 - Junção (parcelas em atraso + a vencer) por *{{juncao}}*\n4 - Regularização das parcelas em atraso sem juros por *{{parcela_desconto}}*\n5 - Simulação para parcelamento no Pix automático ou recorrência no cartão. \n \n*RETORNO EM ATÉ 1 HORA.*\nAcesse o site pagueplay.com ou SAC {{atendimento}}\n \n*A ausência de retorno será interpretada como recusa de negociação, ocasionando o prosseguimento da ação extrajudicial sem novo aviso.*'),
  ('badd7536-522b-414e-8116-7b04af004eca'::UUID,
   E'*ABERTURA DE PROCESSO EM SEU CPF {{cpf}}*\n\nPrezado(a) *{{nome}}*,\n\nConstatamos a confirmação de acordo junto à instituição *{{empresa}}*, a qual *não foi cumprida*. Em razão disso, informamos a *abertura de interesse no processo extrajudicial nº{{contrato}}*, com o objetivo de *regularização do débito* e prevenção de medidas relacionadas a *enriquecimento ilícito e abandono de dívida*.\n\n*Citação registrada para o endereço:*  \n*{{endereco}}-{{cidade}}*\n\n*Prazo final:* Com amparo da *Lei nº 13.140/15*, para fins de conciliação, a empresa disponibiliza a *retirada de acréscimos* e *honorários advocatícios*.\n\n*Opções para resolução imediata:*\n1. *Quitação de todas as parcelas á vista* de *{{valor_com_juros}}* por *{{quitacao}}*  \n2. *Quitação no cartão de crédito (próprio ou terceiros)* em até *12x de R$ 261,00*  \n3. *Anuidade no cartão (plano de pagamento anual)* em até *12x de {{cartao_anual}}*\n4. *Regularização das parcelas em atraso à vista* por *{{parcela_desconto}}*\n5. *Regularização das parcelas em atraso + a que vai vencer por *{{juncao}}*\n6. *Assumo a responsabilidade sobre as medidas cabíveis por falta de pagamento*\n\n*Qual seu posicionamento para resolução hoje?*\nSite: pagueplay - {{atendimento}}',
   E'*ABERTURA DE PROCESSO EM SEU CPF {{cpf}}*\n\nPrezado(a) *{{nome}}*,\n\nConstatamos a confirmação de acordo junto à instituição *{{empresa}}*, a qual *não foi cumprida*. Em razão disso, informamos a *abertura de interesse no processo extrajudicial nº{{contrato}}*, com o objetivo de *regularização do débito* e prevenção de medidas relacionadas a *enriquecimento ilícito e abandono de dívida*.\n\n*Citação registrada para o endereço:*  \n*{{endereco}}-{{cidade}}*\n\n*Prazo final:* Com amparo da *Lei nº 13.140/15*, para fins de conciliação, a empresa disponibiliza a *retirada de acréscimos* e *honorários advocatícios*.\n\n*Opções para resolução imediata:*\n1. *Quitação de todas as parcelas á vista* de *{{valor_com_juros}}* por *{{quitacao}}*  \n2. *Quitação no cartão de crédito (próprio ou terceiros)* em até *12x de R$ 261,00*  \n3. *Anuidade no cartão (plano de pagamento anual)* em até *{{cartao_anual}}*\n4. *Regularização das parcelas em atraso à vista* por *{{parcela_desconto}}*\n5. *Regularização das parcelas em atraso + a que vai vencer por *{{juncao}}*\n6. *Assumo a responsabilidade sobre as medidas cabíveis por falta de pagamento*\n\n*Qual seu posicionamento para resolução hoje?*\nSite: pagueplay - {{atendimento}}'),
