UPDATE public.campanha_facil_mensagens m
   SET corpo = c.depois,
       atualizado_em = now()
  FROM _cf_conversao c
 WHERE m.id = c.id
   AND m.corpo = c.antes;

DO $conferencia$
DECLARE
  v_total      INTEGER;
  v_convertida INTEGER;
  v_mudou      INTEGER;
BEGIN
  SELECT count(*) INTO v_total FROM _cf_conversao;
  SELECT count(*) INTO v_convertida
    FROM public.campanha_facil_mensagens m JOIN _cf_conversao c ON c.id = m.id AND m.corpo = c.depois;
  SELECT count(*) INTO v_mudou
    FROM public.campanha_facil_mensagens m JOIN _cf_conversao c ON c.id = m.id
   WHERE m.corpo <> c.depois;
  RAISE NOTICE 'Mensagens convertidas: % de %. Editadas depois da leitura (ficaram como estão): %.',
    v_convertida, v_total, v_mudou;
END
$conferencia$;

COMMIT;
